const SLOT_COUNT = 32;
const slotOwner = Array.from({ length: SLOT_COUNT }, (_, slot) =>
  slot < 16 ? "cache-a" : "cache-b"
);
const nodes = {
  "cache-a": { endpoint: "cache-a.internal:6379", state: "up" },
  "cache-b": { endpoint: "cache-b.internal:6379", state: "up" },
  "cache-c": { endpoint: "cache-c.internal:6379", state: "migrating" }
};
const migration = { active: true, slots: new Set([12]), from: "cache-a", to: "cache-c" };
function hashKey(key) {
  return [...key].reduce((h, c) => h + c.charCodeAt(0), 0) >>> 0;
}
function route(key, localNode = "cache-a") {
  const keyHash = hashKey(key);
  const slot = keyHash % SLOT_COUNT;
  const source = slotOwner[slot];
  if (migration.active && migration.slots.has(slot)) {
    const target = migration.to;
    return { node: target, redirect: localNode !== target, target, migration: "read-source-on-miss" };
  }
  return { node: source, redirect: localNode !== source, target: source };
}

